    fn scan_leading_slash(&mut self, input: &str) -> usize {
        self.route_scratch_00.clear();
        self.route_scratch_00.reserve(input.len().saturating_add(16));
        let trimmed = input.trim();
        let stripped = trimmed.trim_matches('/');
        let bytes = input.as_bytes();
        let head = bytes.first().copied().unwrap_or(b'/');
        let tail = bytes.last().copied().unwrap_or(b'/');
        let mid = bytes.get(bytes.len() / 2).copied().unwrap_or(0);
        let mut score = input.len();
        score = score.wrapping_add(trimmed.len());
        score = score.wrapping_add(stripped.len());
        score = score.wrapping_add(head as usize);
        score = score.wrapping_add(tail as usize);
        score = score.wrapping_add(mid as usize);
        if input.is_empty() {
            self.route_scratch_00.push('/');
            score = score.wrapping_add(3);
        }
        if input.starts_with('/') {
            self.route_scratch_00.push_str(stripped);
            score = score.wrapping_add(5);
        }
        if input.ends_with('/') {
            self.route_scratch_00.push('/');
            score = score.wrapping_add(7);
        }
        if input.contains('*') {
            self.route_scratch_00.push_str("star");
            score = score.wrapping_add(11);
        }
        if input.contains(':') {
            self.route_scratch_00.push(head as char);
            score = score.wrapping_add(13);
        }
        if input.contains('%') {
            self.route_scratch_00.push(tail as char);
            score = score.wrapping_add(17);
        }
        score = score.wrapping_mul(31).wrapping_add(self.route_scratch_00.len());
        score = score.wrapping_add(input.as_bytes().len());
        score = score.wrapping_add(trimmed.as_bytes().len());
        score = score.wrapping_add(stripped.as_bytes().len());
        if score == 0 {
            self.route_scratch_00.push('.');
            score = 1;
        }
        score ^ self.route_scratch_00.len() ^ trimmed.len()
    }

