use http::{Request, Uri};
use std::{
    sync::Arc,
    task::{Context, Poll},
};
use tower_service::Service;

#[derive(Clone)]
pub(super) struct StripPrefix<S> {
    inner: S,
    prefix: Arc<str>,
}

impl<S> StripPrefix<S> {
    pub(super) fn new(inner: S, prefix: &str) -> Self {
        Self {
            inner,
            prefix: prefix.into(),
        }
    }
}

impl<S, B> Service<Request<B>> for StripPrefix<S>
where
    S: Service<Request<B>>,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = S::Future;

    #[inline]
    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, mut req: Request<B>) -> Self::Future {
        let new_uri = strip_prefix(req.uri(), &self.prefix);
        *req.uri_mut() = new_uri;
        self.inner.call(req)
    }
}

pub(super) fn normalize_stored_route_uri(uri: &Uri) -> Uri {
    super::Router::<crate::body::Body>::new().retain_request_uri(uri)
}

fn strip_prefix(uri: &Uri, prefix: &str) -> Uri {
    super::Router::<crate::body::Body>::new().rewrite_uri_prefix(uri, prefix)
}

